test('header bell keeps acknowledged alerts after reading activity and supports keyboard dismissal',async()=>{
 const calls=[],feed=headerFixture();const page=await mounted('components/HeaderNotifications.tsx',{},async(p,init)=>{calls.push({p,init});if(p.endsWith('/read')){feed.unreadCount=0;feed.badgeCount=1;feed.activity[0].unread=false;return {read:true}}return structuredClone(feed)});
 try{const bell=()=>page.container.querySelector('.notification-bell');assert.match(bell().getAttribute('aria-label'),/1 unresolved alerts, 1 unread/);await page.click(bell());assert.match(page.container.querySelector('[role=dialog]').textContent,/Acknowledged · still unresolved/);assert.equal(calls.filter(c=>c.init?.method==='POST').length,0);await page.click(button(page,'Mark activity read'));assert.match(bell().getAttribute('aria-label'),/1 unresolved alerts, 0 unread/);assert.ok(page.container.textContent.includes('Docker host offline'));const writes=calls.filter(c=>c.init?.method==='POST');assert.equal(writes.length,1);assert.equal(writes[0].p,'/header-notifications/read');assert.deepEqual(JSON.parse(writes[0].init.body),{sequence:1});await act(async()=>document.dispatchEvent(new page.dom.window.KeyboardEvent('keydown',{key:'Escape',bubbles:true})));assert.equal(page.container.querySelector('[role=dialog]'),null);assert.equal(document.activeElement,bell());}finally{await page.close()}
});
test('header bell shows read failures without hiding outstanding warnings and closes outside',async()=>{
 const page=await mounted('components/HeaderNotifications.tsx',{},async(p)=>{if(p.endsWith('/read'))throw Error('Read update failed');return headerFixture()});try{await page.click(page.container.querySelector('.notification-bell'));await page.click(button(page,'Mark activity read'));assert.match(page.container.querySelector('[role=alert]').textContent,/Read update failed/);assert.equal(page.container.querySelector('.notification-bell-count').textContent,'1');await act(async()=>document.body.dispatchEvent(new page.dom.window.Event('pointerdown',{bubbles:true})));assert.equal(page.container.querySelector('[role=dialog]'),null);}finally{await page.close()}
});
test('header bell exposes failed loading and refresh recovers without issuing mutations',async()=>{
 let failed=true;const calls=[];const page=await mounted('components/HeaderNotifications.tsx',{},async(p,init)=>{calls.push({p,init});if(failed)throw Error('Feed unavailable');return headerFixture()});try{await page.click(page.container.querySelector('.notification-bell'));assert.match(page.container.querySelector('[role=alert]').textContent,/Feed unavailable/);assert.equal(button(page,'Mark activity read').disabled,true);failed=false;await page.click(button(page,'Refresh'));assert.ok(!page.container.querySelector('[role=alert]'));assert.match(page.container.textContent,/Docker host offline/);assert.ok(calls.every(c=>!c.init?.method));}finally{await page.close()}
});

test('resource host selector verifies the exact Engine before switching and keeps the previous host on failure',async()=>{let fail=true;const calls=[],page=await mounted('components/DockerHostSelector.tsx',{},async(p,init)=>{calls.push(p);if(p==='/docker/hosts')return {directEnabled:true,hosts:[{id:'a:node',node:'Node A',name:'Docker',online:true},{id:'b:node',node:'Node B',name:'Docker',online:true},{id:'offline:node',name:'Offline',online:false}]};if(p.endsWith('/verify')){if(fail)throw Error('Selected Engine timed out');return {host:{version:'29'}}}throw Error('Unexpected '+p)});try{localStorage.setItem('homecloud_docker_host','a:node');await changeControl(page.container.querySelector('select'),'b:node');assert.equal(localStorage.getItem('homecloud_docker_host'),'a:node');assert.match(page.container.querySelector('[role=alert]').textContent,/timed out/);assert.ok(calls.includes('/docker/hosts/b%3Anode/verify'));assert.equal(page.container.querySelector('option[value="offline:node"]').disabled,true);fail=false;await changeControl(page.container.querySelector('select'),'b:node');assert.equal(localStorage.getItem('homecloud_docker_host'),'b:node');await changeControl(page.container.querySelector('select'),'');assert.ok(calls.includes('/docker/hosts/direct/verify'));assert.equal(localStorage.getItem('homecloud_docker_host'),'');}finally{await page.close()}});
test('AI dialog loads models and tests the entered key, model and API type before saving',async()=>{
 const calls=[],{configurationSchemas}=await import('../../api/src/runtime-configuration.js'),configuration={id:'ai',name:'AI Assistant',disabled:true,fields:configurationSchemas.ai.fields.map(f=>({...f,value:f.defaultValue||'',hasValue:false}))};
 const page=await mounted('components/ConfigurationDialog.tsx',{service:'ai',onClose(){}},async(p,init)=>{calls.push({p,init});if(p.endsWith('/models'))return {result:{models:['gpt-test','o4-mini']}};if(p.endsWith('/test'))return {result:{message:'AI connection verified for the entered settings. Save Configuration to apply them.'}};return configuration});
 try{await changeControl(page.container.querySelector('[aria-label="OpenAI API key"]'),'draft-secret');assert.equal(button(page,'Test Connection').disabled,false);await page.click(button(page,'Load Models'));assert.ok(page.container.querySelector('select[aria-label="Model"] option[value="gpt-test"]'));await changeControl(page.container.querySelector('[aria-label="Model"]'),'gpt-test');await changeControl(page.container.querySelector('[aria-label="OpenAI API type"]'),'chat-completions');page.dom.window.confirm=()=>false;await page.click(button(page,'Test Connection'));assert.ok(!calls.some(c=>c.p.endsWith('/test')));page.dom.window.confirm=()=>true;await page.click(button(page,'Test Connection'));const request=JSON.parse(calls.find(c=>c.p.endsWith('/test')).init.body);assert.deepEqual(request,{confirm:true,configuration:{OPENAI_API_TYPE:'chat-completions',OPENAI_API_KEY:'draft-secret',OPENAI_MODEL:'gpt-test'}});assert.ok(!calls.some(c=>c.init?.method==='PUT'));assert.match(page.container.querySelector('[role=status]').textContent,/Save Configuration/);assert.equal(page.container.querySelector('[aria-label="OpenAI API key"]').value,'draft-secret');assert.equal(button(page,'Save Configuration').disabled,false);}finally{await page.close()}
});
test('AI custom models retain saved credentials and actionable test failures keep the draft',async()=>{
 const calls=[],{configurationSchemas}=await import('../../api/src/runtime-configuration.js'),configuration={id:'ai',name:'AI Assistant',disabled:false,fields:configurationSchemas.ai.fields.map(f=>({...f,value:f.defaultValue||'',hasValue:f.key==='OPENAI_API_KEY'}))};
 const page=await mounted('components/ConfigurationDialog.tsx',{service:'ai',onClose(){}},async(p,init)=>{calls.push({p,init});if(p.endsWith('/test'))throw Error('OpenAI API quota is exhausted. Check API billing and project spending limits.');if(p.endsWith('/models'))throw Error('OpenAI denied access. Check API key permissions.');return configuration});
 try{await page.click(button(page,'Load Models'));assert.match(page.container.querySelector('[role=alert]').textContent,/permissions/);await changeControl(page.container.querySelector('[aria-label="Model"]'),'__custom');await changeControl(page.container.querySelector('[aria-label="Custom model ID"]'),'ft:gpt-test:org:custom');await page.click(button(page,'Test Connection'));const request=JSON.parse(calls.find(c=>c.p.endsWith('/test')).init.body);assert.equal(request.configuration.OPENAI_MODEL,'ft:gpt-test:org:custom');assert.ok(!Object.hasOwn(request.configuration,'OPENAI_API_KEY'));assert.match(page.container.querySelector('[role=alert]').textContent,/quota/);assert.equal(page.container.querySelector('[aria-label="Custom model ID"]').value,'ft:gpt-test:org:custom');assert.equal(button(page,'Test Connection').disabled,false);assert.ok(!calls.some(c=>c.init?.method==='PUT'));}finally{await page.close()}
});

test('header bell keeps recent activity visible without counting it, including older API totals',async()=>{
 const feed={...headerFixture(),attention:[],attentionCount:0,badgeCount:23,unreadCount:23};const page=await mounted('components/HeaderNotifications.tsx',{},async()=>feed);
 try{assert.equal(page.container.querySelector('.notification-bell-count'),null);await page.click(page.container.querySelector('.notification-bell'));assert.match(page.container.textContent,/Recent activity/);assert.match(page.container.textContent,/VM #106 start: queued/);assert.equal(button(page,'Mark activity read').disabled,false);}finally{await page.close()}
});

test('About does not invent metadata for an unbuilt development API',async()=>{const page=await mounted('components/AboutSettings.tsx',{data:{system:{version:'3.0.0'}},owner:false,search:'Version'},async()=>({}));try{assert.match(page.container.textContent,/Development build/);assert.match(page.container.textContent,/Not embedded in this build/);assert.ok(!page.container.textContent.includes('2026-'));}finally{await page.close()}});

test('Discord, Telegram, SMTP and TrueNAS test entered configuration before saving or enabling',async()=>{
 const {configurationSchemas}=await import('../../api/src/runtime-configuration.js'),samples={discord:{DISCORD_WEBHOOK_URL:'https://discord.com/api/webhooks/123/draft-secret'},telegram:{TELEGRAM_BOT_TOKEN:'123:draft-secret',TELEGRAM_CHAT_ID:'-123'},email:{SMTP_HOST:'smtp.example.test',SMTP_PORT:'587',SMTP_USER:'',SMTP_PASSWORD:'',NOTIFICATION_EMAIL_FROM:'from@example.test',NOTIFICATION_EMAIL_TO:'to@example.test',SMTP_CA_PEM:''},truenas:{TRUENAS_URL:'https://nas.example.test',TRUENAS_API_KEY:'draft-secret',TRUENAS_API_MODE:'current',TRUENAS_CA_PEM:''}};
 for(const [service,values] of Object.entries(samples)){const calls=[],configuration={id:service,name:configurationSchemas[service].name,disabled:true,fields:configurationSchemas[service].fields.map(f=>({...f,value:f.defaultValue||(f.type==='select'||f.type==='number'?values[f.key]:''),hasValue:false}))},page=await mounted('components/ConfigurationDialog.tsx',{service,onClose(){}},async(p,init)=>{calls.push({p,init});return p.endsWith('/test')?{result:{message:'Draft verified. Save Configuration to apply.'}}:configuration});try{for(const field of configuration.fields.filter(f=>values[f.key]&&f.type!=='select'))await changeControl(page.container.querySelector(`[aria-label="${field.label}"]`),values[field.key]);assert.equal(button(page,'Test Connection').disabled,false);if(service!=='truenas'){page.dom.window.confirm=()=>false;await page.click(button(page,'Test Connection'));assert.ok(!calls.some(c=>c.p.endsWith('/test')));page.dom.window.confirm=()=>true;}await page.click(button(page,'Test Connection'));const request=JSON.parse(calls.find(c=>c.p.endsWith('/test')).init.body);assert.equal(request.confirm,service!=='truenas');for(const [key,value] of Object.entries(values))if(value)assert.equal(request.configuration[key],value);assert.ok(!calls.some(c=>c.init?.method==='PUT'||c.init?.method==='DELETE'));assert.match(page.container.querySelector('[role=status]').textContent,/Save Configuration/);assert.equal(button(page,'Save Configuration').disabled,false);}finally{await page.close()}}
});
test('configuration tests validate missing inputs and preserve changed secrets on failure',async()=>{const calls=[],page=await mounted('components/ConfigurationDialog.tsx',{service:'discord',onClose(){}},async(p,init)=>{calls.push({p,init});if(p.endsWith('/test'))throw Error('Discord endpoint was not found. Check that the webhook is still valid.');return {name:'Discord',disabled:false,fields:[{key:'DISCORD_WEBHOOK_URL',label:'Webhook URL',type:'password',required:true,value:'',hasValue:false}]}});try{await page.click(button(page,'Test Connection'));assert.ok(!calls.some(c=>c.p.endsWith('/test')));await changeControl(page.container.querySelector('input'),'https://discord.com/api/webhooks/123/retain-secret');await page.click(button(page,'Test Connection'));assert.match(page.container.querySelector('[role=alert]').textContent,/endpoint was not found/);assert.equal(page.container.querySelector('input').value,'https://discord.com/api/webhooks/123/retain-secret');assert.equal(button(page,'Test Connection').disabled,false);assert.equal(button(page,'Save Configuration').disabled,false);}finally{await page.close()}});

test('new notification setup dialogs retain encrypted secrets and stage per-channel delivery selectors',async()=>{const {configurationSchemas}=await import('../../api/src/runtime-configuration.js'),samples={slack:{SLACK_WEBHOOK_URL:'https://hooks.slack.com/services/T/B/secret'},teams:{TEAMS_WEBHOOK_URL:'https://prod.example.logic.azure.com/workflows/secret?sig=key'},pushover:{PUSHOVER_APP_TOKEN:'A'.repeat(30),PUSHOVER_USER_KEY:'B'.repeat(30)},gotify:{GOTIFY_URL:'https://gotify.example.test',GOTIFY_APP_TOKEN:'secret'},webhook:{WEBHOOK_URL:'https://receiver.example.test/hook',WEBHOOK_BEARER_TOKEN:'secret'},ifttt:{IFTTT_EVENT:'homecloud_alert',IFTTT_WEBHOOK_KEY:'secret'}};for(const [service,values] of Object.entries(samples)){const calls=[],schema=configurationSchemas[service];let configuration={id:service,name:schema.name,disabled:false,fields:schema.fields.map(f=>({...f,value:f.defaultValue||'',hasValue:false}))};const page=await mounted('components/ConfigurationDialog.tsx',{service,onClose(){}},async(p,init)=>{calls.push({p,init});if(p.endsWith('/test'))return {result:{message:'Test notification delivered. Save Configuration to apply.'}};if(init?.method==='PUT'){const body=JSON.parse(init.body);configuration={...configuration,fields:schema.fields.map(f=>({...f,value:f.type==='password'?'':body[f.key]||'',hasValue:!!body[f.key]}))};return {result:configuration}}return configuration});try{for(const [key,value] of Object.entries(values)){const label=schema.fields.find(f=>f.key===key).label;await changeControl(page.container.querySelector(`[aria-label="${label}"]`),value);}const picker=page.container.querySelector('.notification-filter-picker');assert.equal(picker.querySelectorAll('input[type=checkbox]').length,6);await page.click(picker.querySelector('.notification-filter-all input'));for(const label of ['Critical','Warning','Recoveries'])await page.click([...picker.querySelectorAll('label')].find(l=>l.textContent===label).querySelector('input'));assert.ok(!calls.some(c=>c.init?.method==='PUT'));await page.click(button(page,'Test Connection'));assert.equal(JSON.parse(calls.find(c=>c.p.endsWith('/test')).init.body).configuration[service.toUpperCase()+'_NOTIFICATION_FILTER'],'critical,warning,resolved');await page.click(button(page,'Save Configuration'));assert.equal(JSON.parse(calls.find(c=>c.init?.method==='PUT').init.body)[service.toUpperCase()+'_NOTIFICATION_FILTER'],'critical,warning,resolved');assert.equal(page.container.querySelectorAll('.notification-filter-options input:checked').length,3);assert.equal(page.container.querySelector('.notification-filter-all input').indeterminate,true);for(const field of schema.fields.filter(f=>f.type==='password'))assert.equal(page.container.querySelector(`[aria-label="${field.label}"]`).value,'');}finally{await page.close()}}});
test('notification channels include all nine setup entries and corresponding history filters',async()=>{const page=await settingsPage();try{await page.click(button(page,'Notifications'));const rows=page.container.querySelectorAll('.notification-settings-channel');assert.equal(rows.length,9);for(const name of ['Slack','Microsoft Teams','Pushover','Gotify','Custom Webhook','IFTTT'])assert.ok([...rows].some(r=>r.textContent.includes(name)));const select=page.container.querySelector('[aria-label="Notification channel"]');assert.equal(select.options.length,10);}finally{await page.close()}});

test('notification checkboxes preserve a legacy selection and block empty saves and tests',async()=>{const {configurationSchemas}=await import('../../api/src/runtime-configuration.js'),calls=[],schema=configurationSchemas.discord,page=await mounted('components/ConfigurationDialog.tsx',{service:'discord',onClose(){}},async(p,init)=>{calls.push({p,init});return {id:'discord',name:'Discord',fields:schema.fields.map(f=>({...f,value:f.type==='password'?'':'critical',hasValue:true}))}});try{const options=()=>[...page.container.querySelectorAll('.notification-filter-options input')];assert.deepEqual(options().map(i=>i.checked),[true,false,false,false,false]);await page.click(options()[0]);await page.click(button(page,'Save Configuration'));await page.click(button(page,'Test Connection'));assert.match(page.container.querySelector('[role=alert]').textContent,/Select at least one/);assert.ok(!calls.some(c=>['PUT','POST'].includes(c.init?.method)));await page.click(page.container.querySelector('.notification-filter-all input'));assert.ok(options().every(i=>i.checked));assert.equal(page.container.querySelector('.notification-filter-all input').indeterminate,false);}finally{await page.close()}});

test('connector update popup targets one paired node and clears credentials after queued maintenance',async()=>{const calls=[],revision='f'.repeat(64),page=await mounted('components/ConnectorUpdateDialog.tsx',{node:{id:'paired',name:'Node01',hostname:'node01',update:{version:5,revision,available:true}},onClose(){},onUpdated(){}},async(p,init)=>{calls.push({p,init});if(p==='/ssh/fingerprint')return {fingerprint:'SHA256:'+'a'.repeat(43)};return {update:init?.method==='POST'?{state:'connecting',revision,message:'Connecting to selected paired host.'}:null};});try{await act(async()=>{await new Promise(r=>setTimeout(r,350))});await changeControl(page.container.querySelector('[aria-label="SSH / sudo password"]'),'fixture-secret');for(const check of page.container.querySelectorAll('input[type=checkbox][required]'))await page.click(check);await act(async()=>{page.container.querySelector('form').dispatchEvent(new page.dom.window.Event('submit',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,0));});const write=calls.find(c=>c.p==='/node-agents/paired/update'&&c.init?.method==='POST');assert.ok(write);const body=JSON.parse(write.init.body);assert.equal(body.revision,revision);assert.equal(body.confirm,true);assert.equal(body.host,'node01');assert.equal(page.container.querySelector('[aria-label="SSH / sudo password"]').value,'');assert.match(page.container.textContent,/Connecting to selected/);assert.ok(!JSON.stringify(localStorage).includes('fixture-secret'));assert.ok(!calls.some(c=>c.p.includes('/guest/')));}finally{await page.close()}});

test('Connections offers one update notice per paired node and opens its update flow',async()=>{const revision='a'.repeat(64),node={id:'paired',name:'Node01',hostname:'node01',kind:'proxmox',online:true,version:5,update:{version:5,revision,available:true},hosts:[]},page=await mounted('components/ConnectionManager.tsx',{},async p=>{if(p==='/auth/me')return {user:{role:'owner'}};if(p==='/node-agents')return {nodes:[node]};if(p==='/connections/health')return {connections:[{id:'paired',agentId:'paired',kind:'proxmox',provider:'proxmox',name:'Node01',endpoint:'node01',method:'Paired Proxmox node',status:'online',issues:[]},{id:'paired:qemu/101',agentId:'paired',kind:'docker',provider:'docker',name:'Guest',endpoint:'node01',status:'online',issues:[]}]};if(p==='/connections/proxmox')return {cluster:null};if(p==='/connections/docker')return {connection:null};if(p==='/docker/hosts')return {hosts:[]};if(p.endsWith('/update'))return {update:null};if(p==='/ssh/fingerprint')return {fingerprint:'SHA256:'+'a'.repeat(43)};return {}});try{assert.equal(page.container.querySelectorAll('.connector-update-notice .btn').length,1);await page.click(button(page,'Update connector · Node01'));assert.match(page.container.querySelector('[role=dialog]').textContent,/Update connector · Node01/);assert.equal(page.container.querySelector('[aria-label="Paired host SSH address"]').value,'node01');}finally{await page.close()}});

test('connector popup uses the Proxmox IP and lets users retry DNS failures without changing address',async()=>{const calls=[],page=await mounted('components/ConnectorUpdateDialog.tsx',{node:{id:'paired',name:'Node01',hostname:'node01',update:{version:5,revision:'a'.repeat(64)}},onClose(){},onUpdated(){}},async(p,init)=>{calls.push({p,init});if(p.endsWith('/ssh-target'))return {host:'192.0.2.10',source:'proxmox',message:'Address reported by Proxmox.'};if(p==='/ssh/fingerprint'){if(calls.filter(c=>c.p===p).length===1)throw Error('SSH connection failed: getaddrinfo EAI_AGAIN node01');return {fingerprint:'SHA256:'+'a'.repeat(43)}}return {update:null}});try{await act(async()=>{await new Promise(r=>setTimeout(r,350))});assert.equal(page.container.querySelector('[aria-label="Paired host SSH address"]').value,'192.0.2.10');assert.match(page.container.querySelector('[role=alert]').textContent,/Enter the paired host’s IP address/);assert.equal(page.container.querySelector('.ssh-fingerprint input').disabled,true);await page.click(button(page,'Read SSH Fingerprint'));await act(async()=>{await new Promise(r=>setTimeout(r,350))});assert.equal(page.container.querySelector('.ssh-fingerprint input').disabled,false);assert.equal(page.container.querySelector('[role=alert]'),null);assert.equal(JSON.parse(calls.filter(c=>c.p==='/ssh/fingerprint').at(-1).init.body).host,'192.0.2.10');await page.click(page.container.querySelector('.ssh-fingerprint input'));await changeControl(page.container.querySelector('[aria-label="Paired host SSH address"]'),'192.0.2.11');assert.equal(page.container.querySelector('.ssh-fingerprint input').checked,false);}finally{await page.close()}});
